<?php require_once __DIR__.'/../bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$anime=(int)($_GET['anime_id']??0);$e=['anime_id'=>$anime,'number'=>'','title'=>'','thumbnail'=>'','active'=>1];if($id){$s=$pdo->prepare('SELECT * FROM episodes WHERE id=?');$s->execute([$id]);$e=$s->fetch()?:$e;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$v=[$_POST['anime_id'],(float)$_POST['number'],trim($_POST['title']),trim($_POST['thumbnail']),isset($_POST['active'])?1:0];if($id){$v[]=$id;$q=$pdo->prepare('UPDATE episodes SET anime_id=?,number=?,title=?,thumbnail=?,active=? WHERE id=?');}else$q=$pdo->prepare('INSERT INTO episodes(anime_id,number,title,thumbnail,active) VALUES(?,?,?,?,?)');$q->execute($v);header('Location: episodes.php?anime_id='.(int)$_POST['anime_id']);exit;}$title='Episode editor — AniRead';include __DIR__.'/../includes/header.php';?><h1><?= $id?'Edit':'Add' ?> episode</h1><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Anime</label><select name="anime_id" required><?php foreach($pdo->query('SELECT id,title FROM anime ORDER BY title') as $a):?><option value="<?=$a['id']?>" <?=$a['id']==$e['anime_id']?'selected':''?>><?=e($a['title'])?></option><?php endforeach;?></select><label>Episode number</label><input class="input" name="number" type="number" step="0.1" value="<?=e($e['number'])?>" required><label>Title</label><input class="input" name="title" value="<?=e($e['title'])?>"><label>Thumbnail URL</label><input class="input" name="thumbnail" value="<?=e($e['thumbnail'])?>"><label><input type="checkbox" name="active" <?=$e['active']?'checked':''?>> Active</label><br><button class="btn">Save</button></form><?php include __DIR__.'/../includes/footer.php';
